fn main() -> Result<(), Box<dyn std::error::Error>> {
    let app = build_cli();
    let matches = app.get_matches();

    // Handle version
    if matches.get_flag("version") {
        println!("bat 0.26.1 (610b77c)");
        return Ok(());
    }

    // Handle help
    if matches.get_flag("help") {
        println!("A cat(1) clone with wings.\n");
        println!("Usage: bat [OPTIONS] [FILE]...");
        println!("       bat <COMMAND>\n");
        println!("Arguments:");
        println!("  [FILE]...  File(s) to print / concatenate. Use '-' for standard input.\n");
        println!("Options:");
        println!("  -A, --show-all");
        println!("          Show non-printable characters (space, tab, newline, ..).");
        return Ok(());
    }

    // Get files
    let files: Vec<&str> = matches.get_many("file")
        .map(|v| v.collect())
        .unwrap_or_default();

    // Process files or stdin
    if files.is_empty() || (files.len() == 1 && files[0] == "-") {
        let mut buffer = String::new();
        io::stdin().read_to_string(&mut buffer)?;

        if matches.get_flag("quiet-empty") && buffer.is_empty() {
            return Ok(());
