        for file in files {
            if file == "-" {
                let mut buffer = String::new();
                io::stdin().read_to_string(&mut buffer)?;
                println!("{}", buffer.trim_end());
            } else {
                let content = fs::read_to_string(file)?;
                println!("{}", content.trim_end());
            }
        }
    }

    Ok(())
}

