cd /workspace && cat > src/main.rs << 'EOF'
use std::env;
use std::fs;
use std::io::{self, Read, BufRead, BufReader};
use std::path::Path;
use std::process;

mod cli;
mod formatter;
mod syntax;
mod themes;

use cli::Args;
use formatter::Formatter;

const VERSION: &str = "0.26.1";
const COMMIT_HASH: &str = "610b77c";

fn main() {
    let args = cli::parse_args();

    if let Err(e) = run(args) {
        eprintln!("bat: error: {}", e);
        process::exit(1);
    }
}

fn run(args: Args) -> Result<(), Box<dyn std::error::Error>> {
    // Handle special commands
    if args.show_version {
        println!("bat {} ({})", VERSION, COMMIT_HASH);
        return Ok(());
    }

    if args.show_help {
        print_help();
        return Ok(());
    }

    if args.list_languages {
        print_languages();
        return Ok(());
    }

    if args.list_themes {
        print_themes();
        return Ok(());
    }

    if args.diagnostic {
        print_diagnostic();
        return Ok(());
    }

    // Create formatter with the arguments
    let mut formatter = Formatter::new(&args);

    // Process input files or stdin
    if args.files.is_empty() {
        // Read from stdin
        let mut input = String::new();
        io::stdin().read_to_string(&mut input)?;

        if args.quiet_empty && input.trim().is_empty() {
            return Ok(());
        }

        formatter.format(&input, None)?;
    } else {
        // Process each file
        for (idx, file) in args.files.iter().enumerate() {
            if file == "-" {
                // Read from stdin
                let mut input = String::new();
                io::stdin().read_to_string(&mut input)?;

                if args.quiet_empty && input.trim().is_empty() {
                    continue;
                }

                formatter.format(&input, None)?;
            } else {
                // Read from file
                let content = fs::read_to_string(file)?;

                if args.quiet_empty && content.trim().is_empty() {
                    continue;
                }

                formatter.format(&content, Some(file))?;
            }

            // Add separation between files if needed
            if idx < args.files.len() - 1 && args.show_file_header {
                println!();
            }
        }
    }

    Ok(())
}

fn print_help() {
    println!("A cat(1) clone with wings.\n");
    println!("Usage: bat [OPTIONS] [FILE]...");
    println!("       bat <COMMAND>\n");
    println!("Arguments:");
    println!("  [FILE]...  File(s) to print / concatenate. Use '-' for standard input.\n");
    println!("Options:");
    println!("  -A, --show-all");
    println!("          Show non-printable characters (space, tab, newline, ..).");
    println!("      --nonprintable-notation <notation>");
    println!("          Set notation for non-printable characters.");
    println!("      --binary <behavior>");
    println!("          How to treat binary content. (default: no-printing)");
    println!("  -p, --plain...");
    println!("          Show plain style (alias for '--style=plain').");
    println!("  -l, --language <language>");
    println!("          Set the language for syntax highlighting.");
    println!("      --fallback-syntax <fallback-syntax>");
    println!("          Set a fallback language for undetected syntaxes. [aliases: --fallback-language]");
    println!("  -H, --highlight-line <N:M>");
    println!("          Highlight lines N through M.");
    println!("      --file-name <name>");
    println!("          Specify the name to display for a file.");
    println!("  -d, --diff");
    println!("          Only show lines that have been added/removed/modified.");
    println!("      --tabs <T>");
    println!("          Set the tab width to T spaces.");
    println!("      --wrap <mode>");
    println!("          Specify the text-wrapping mode (*auto*, never, character, word).");
    println!("  -S, --chop-long-lines");
    println!("          Truncate all lines longer than screen width. Alias for '--wrap=never'.");
    println!("  -n, --number");
    println!("          Show line numbers (alias for '--style=numbers').");
    println!("      --color <when>");
    println!("          When to use colors (*auto*, never, always).");
    println!("      --italic-text <when>");
    println!("          Use italics in output (always, *never*)");
    println!("      --decorations <when>");
    println!("          When to show the decorations (*auto*, never, always).");
    println!("      --paging <when>");
    println!("          Specify when to use the pager, or use `-P` to disable (*auto*, never, always).");
    println!("  -m, --map-syntax <glob:syntax>");
    println!("          Use the specified syntax for files matching the glob pattern ('*.cpp:C++').");
    println!("      --theme <theme>");
    println!("          Set the color theme for syntax highlighting.");
    println!("      --theme-light <theme>");
    println!("          Sets the color theme for syntax highlighting used for light backgrounds.");
    println!("      --theme-dark <theme>");
    println!("          Sets the color theme for syntax highlighting used for dark backgrounds.");
    println!("      --list-themes");
    println!("          Display all supported highlighting themes.");
    println!("  -s, --squeeze-blank");
    println!("          Squeeze consecutive empty lines.");
    println!("      --style <components>");
    println!("          Comma-separated list of style elements to display (*default*, auto, full, plain, changes,");
    println!("          header, header-filename, header-filesize, grid, rule, numbers, snip).");
    println!("  -r, --line-range <N:M>");
    println!("          Only print the lines from N to M.");
    println!("  -L, --list-languages");
    println!("          Display all supported languages.");
    println!("  -u, --unbuffered");
    println!("          Enable unbuffered input reading for streaming use cases.");
    println!("      --completion <SHELL>");
    println!("          Show shell completion for a certain shell. [possible values: bash, fish, zsh, ps1]");
    println!("  -E, --quiet-empty");
    println!("          Produce no output when the input is empty.");
    println!("  -h, --help");
    println!("          Print help (see more with '--help')");
    println!("  -V, --version");
    println!("          Print version");
}

fn print_languages() {
    let languages = syntax::get_all_languages();
