cd /workspace && cat > src/formatter.rs << 'EOF'
use crate::cli::Args;

pub struct Formatter {
    args: Args,
}

impl Formatter {
    pub fn new(args: &Args) -> Self {
        Formatter {
            args: args.clone(),
        }
    }

    pub fn format(&self, content: &str, filename: Option<&str>) -> Result<(), Box<dyn std::error::Error>> {
        let lines: Vec<&str> = content.lines().collect();

        // Apply line range filter
        let lines = if let Some(ref range) = self.args.line_range {
            self.apply_line_range(&lines, range)
        } else {
            lines
        };

        // Apply squeeze blank
        let lines = if self.args.squeeze_blank {
            self.apply_squeeze_blank(&lines)
        } else {
            lines
        };

        // Apply show-all transformation and tab width first
        let lines: Vec<String> = if self.args.show_all {
            lines.iter().map(|line| {
                let line = self.apply_tab_width(line);
                self.show_all_chars(&line)
            }).collect()
        } else {
            lines.iter().map(|line| self.apply_tab_width(line)).collect()
        };

        // Print output
        if self.args.number {
            let max_width = (lines.len()).to_string().len().max(3);
            for (idx, line) in lines.iter().enumerate() {
                let line_num = idx + 1;
                println!("{:>width$} {}", line_num, line, width = max_width);
            }
        } else {
            for line in lines {
                println!("{}", line);
            }
        }

        Ok(())
    }

    fn apply_line_range<'a>(&self, lines: &[&'a str], range: &str) -> Vec<&'a str> {
        let parts: Vec<&str> = range.split(':').collect();

        let start = if parts[0].is_empty() {
            0
        } else {
            parts[0].parse::<usize>().unwrap_or(1).saturating_sub(1)
        };

        let end = if parts.len() > 1 && !parts[1].is_empty() {
            parts[1].parse::<usize>().unwrap_or(lines.len())
        } else {
            lines.len()
        };

        lines
            .iter()
            .enumerate()
            .filter(|(idx, _)| *idx >= start && *idx < end)
            .map(|(_, line)| *line)
            .collect()
    }

    fn apply_squeeze_blank<'a>(&self, lines: &[&'a str]) -> Vec<&'a str> {
        let mut result = Vec::new();
        let mut prev_empty = false;

        for line in lines {
            let is_empty = line.trim().is_empty();
            if is_empty && prev_empty {
                continue;
            }
            result.push(*line);
            prev_empty = is_empty;
        }

        result
    }

    fn show_all_chars(&self, line: &str) -> String {
        let mut result = String::new();
        for ch in line.chars() {
            match ch {
                ' ' => result.push('·'),
                '\t' => result.push_str("├─┤"),
                '\r' => result.push_str("␍"),
                _ if ch.is_control() => {
                    result.push('·');
                }
                _ => result.push(ch),
            }
        }
        // Always add the end-of-line marker
        result.push_str("␊");
        result
    }

    fn apply_tab_width(&self, line: &str) -> String {
        if self.args.tabs == 0 {
            line.to_string()
        } else {
            line.replace('\t', &" ".repeat(self.args.tabs))
        }
    }
}
