fn main() {
    let args = cli::parse_args();

    if let Err(e) = run(args) {
        eprintln!("bat: error: {}", e);
        process::exit(1);
    }
}

fn run(args: Args) -> Result<(), Box<dyn std::error::Error>> {
    // Handle special commands
    if args.show_version {
        println!("bat {} ({})", VERSION, COMMIT_HASH);
        return Ok(());
    }

    if args.show_help {
        print_help();
        return Ok(());
    }

    if args.list_languages {
        print_languages();
        return Ok(());
    }

    if args.list_themes {
        print_themes();
        return Ok(());
    }

    if args.diagnostic {
        print_diagnostic();
        return Ok(());
    }

    // Create formatter with the arguments
    let formatter = Formatter::new(&args);

    // Process input files or stdin
    if args.files.is_empty() {
        // Read from stdin
        let mut input = String::new();
        io::stdin().read_to_string(&mut input)?;

        if args.quiet_empty && input.trim().is_empty() {
            return Ok(());
        }

        formatter.format(&input, None)?;
    } else {
        // Process each file
        for file in args.files.iter() {
            if file == "-" {
                // Read from stdin
                let mut input = String::new();
                io::stdin().read_to_string(&mut input)?;

                if args.quiet_empty && input.trim().is_empty() {
                    continue;
                }

                formatter.format(&input, None)?;
            } else {
                // Read from file
                let content = fs::read_to_string(file)?;

                if args.quiet_empty && content.trim().is_empty() {
                    continue;
                }

                formatter.format(&content, Some(file))?;
            }
        }
    }

    Ok(())
}

