fn print_languages() {
    let languages = syntax::get_all_languages();
    for lang in languages {
        println!("{}", lang);
    }
}

fn print_themes() {
    let themes = themes::get_all_themes();
    for theme in themes {
        println!("{}", theme);
    }
}

